'use strict'
const assert = require('node:assert')
const u = require('..')

assert.strictEqual(u.clamp(5, 0, 10), 5)
assert.strictEqual(u.clamp(-3, 0, 10), 0)
assert.strictEqual(u.clamp(12, 0, 10), 10)
assert.strictEqual(u.clamp(10, 0, 10), 10)
assert.strictEqual(u.inRange(3, 1, 5), true)
assert.strictEqual(u.inRange(1, 1, 5), true)
assert.strictEqual(u.inRange(5, 1, 5), true)
assert.strictEqual(u.inRange(6, 1, 5), false)
assert.strictEqual(u.inRange(0, 1, 5), false)
assert.strictEqual(u.sumTo(4), 10)
assert.strictEqual(u.sumTo(1), 1)
assert.strictEqual(u.sumTo(0), 0)
assert.strictEqual(u.maxOf([3, 9, 2]), 9)
assert.strictEqual(u.maxOf([-4, -2, -8]), -2)
assert.strictEqual(u.maxOf([7]), 7)
assert.strictEqual(u.maxOf([]), null)
assert.strictEqual(u.percent(1, 4), 25)
assert.strictEqual(u.percent(2, 3), 67)
assert.strictEqual(u.percent(5, 0), 0)
